source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    edge_counts = Counter()
    for c in (0, w - 1):
        edge_counts.update(v for v in (g[r][c] for r in range(h)) if v != bg)
    for r in (0, h - 1):
        edge_counts.update(v for v in (g[r][c] for c in range(w)) if v != bg)
    border = edge_counts.most_common(1)[0][0]
    markers = [(r, c, g[r][c]) for r in range(h) for c in range(w)
               if g[r][c] not in (bg, border)]

    def runs(vals):
        ids = [i for i, v in enumerate(vals) if v == border]
        if not ids:
            return []
        out, a, b = [], ids[0], ids[0]
        for i in ids[1:]:
            if i == b + 1:
                b = i
            else:
                out.append((a, b))
                a = b = i
        out.append((a, b))
        return out

    left = runs([g[r][0] for r in range(h)])
    right = runs([g[r][w-1] for r in range(h)])
    top = runs(g[0])
    bottom = runs(g[h-1])
    # Opposing vertical edge segments define a horizontal wrap.
    if left and right:
        L, R = max(left, key=lambda x: x[1]-x[0]), max(right, key=lambda x: x[1]-x[0])
        for r, c, color in markers:
            g[r][c] = 4
            if L[0] <= r <= L[1]:
                for x in range(1, c):
                    if g[r][x] == bg: g[r][x] = color
                rr = r + (R[0] - L[0])
                if 0 <= rr < h:
                    for x in range(1, w-1):
                        if g[rr][x] == bg: g[rr][x] = color
            elif R[0] <= r <= R[1]:
                for x in range(c+1, w-1):
                    if g[r][x] == bg: g[r][x] = color
                rr = r + (L[0] - R[0])
                if 0 <= rr < h:
                    for x in range(1, w-1):
                        if g[rr][x] == bg: g[rr][x] = color
        return g

    # Opposing horizontal edge segments define a vertical wrap.
    if top and bottom:
        T, B = max(top, key=lambda x: x[1]-x[0]), max(bottom, key=lambda x: x[1]-x[0])
        shift = T[0] - B[0]
        for r, c, color in markers:
            g[r][c] = 4
            # A marker aligned with the top segment shoots to that segment;
            # its shifted counterpart fills the opposite span.
            if T[0] <= c <= T[1]:
                for y in range(1, r):
                    if g[y][c] == bg: g[y][c] = color
                cc = c - shift
                if 0 <= cc < w:
                    for y in range(1, h-1):
                        if g[y][cc] == bg: g[y][cc] = color
            else:
                cc = c + shift
                if 0 <= cc < w:
                    for y in range(1, h):
                        if g[y][cc] == bg: g[y][cc] = color
        return g
    return g
